 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_1_PreSelChangeNotify = function(nIndex) {
    /*	if (nIndex == 1) {
    		fn_list_sync_1();
    	} else if (nIndex == 2) {
    		fn_list_sync_2();
    	}*/
};

/**
     * @method
     * @name btn_toexcel_onclick
     * @description 「엑셀다운로드」 클릭 이벤트
     * @returns {void}
     * @hidden N
     */
scwin.btn_toexcel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05240.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (MxTab_1.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_Grid1, {fileName: "기술성장기업", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_Grid2, {fileName: "이익미실현기업", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.btn_toexcel_onclick" });
    }
};

/**
 * @method
 * @name btn_select_onclick
 * @description btn_select 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        if (MxTab_1.getSelectedTabIndex() === 1) {
            await scwin.listSync1();
        } else if (MxTab_1.getSelectedTabIndex() === 2) {
            await scwin.listSync2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05240.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.btn_close_onclick" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        // showPanCnd(nIndex);
        if (nIndex === 1) {
            await scwin.listSync1();
        } else if (nIndex === 2) {
            await scwin.listSync2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05240.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
