    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
        if (scwin.gDepCd === '') {
            cmb_EMP_NO.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05240.dts_emp_OnFilter" });
    }
};

