/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.setPara(row);
        const wth = 580;
        const hgt = 220;
        const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        const options = {
            id: "ULDSTF05245",
            title: "영업손실 유예 관리",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstproc/ULDSTF05245.gfm", options);

        // fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05240.grd_Grid_OnDblClick" });
    }
};

