/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let gCnt = 0;
    for (let k = 1; k <= dts_Grid.getRowCount(); k++) {
        gStat = dts_Grid.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            if (dts_Grid.getCellData(k, "DEP_CD") === js_dep_cd) {
                dts_Grid.setCellData(k, "ADJPRN_EMP_NO", js_emp_no);
                gCnt++;
            } else {
                await $c.win.alert(k + "번째 " + dts_Grid.getCellData(k, "COM_ABBRV") + "항목은 해당팀만 수정할 수 있습니다.");
                return;
            }
        }
    }
    if (gCnt === 0) {
        await $c.win.alert("수정할 내용이 없습니다.");
        return;
    }
    if (window.confirm(gCnt + "건 수정 하시겠습니까?")) {
        const url = "/SkillGrwComGrace.do?method=insertSkillGrwComGrace&SCREN_ID=" + "ULDSTF05240.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_save.Post();
    }
};

/**
