    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    grd_Grid1.ActiveIndex = 1;
    scwin.showPanCnd(MxTab_1.getSelectedTabIndex());
    await scwin.setCode();
    await scwin.listSync1();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
